27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "city")
43	    @NotEmpty
44	    private String city;
45	
46	    @Column(name = "telephone")
47	    @NotEmpty
48	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form")
49	    private String telephone;
50	
51	    @Column(name = "email")
52	    private String email;
53	
54	    @Column(name = "postcode")
55	    private String postcode;
56	
57	    @Column(name = "registration_date")
58	    private LocalDate registrationDate;
59	
60	    @Column(name = "birth_date")
61	    private LocalDate birthDate;
62	
63	    @Column(name = "customer_code")
64	    private String customerCode;
65	
66	    @Column(name = "household_id")
67	    private String householdId;
68	
69	    @Column(name = "namesake_count")
70	    private Integer namesakeCount;
71	
72	    @Column(name = "bulk_signup_warning")
73	    private Boolean bulkSignupWarning;
74	
75	    @Column(name = "household_size")
76	    private Integer householdSize;
77	
78	    @Column(name = "possible_duplicate")
79	    private Boolean possibleDuplicate;
80	
81	    @Column(name = "possible_duplicate_of")
82	    private Integer possibleDuplicateOf;
83	
84	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
85	    private Set<Pet> pets;
86	
87	    public String getAddress() {
88	        return this.address;
89	    }
90	
91	    public void setAddress(String address) {
92	        this.address = address;
93	    }
94	
95	    public String getCity() {
96	        return this.city;
97	    }
98	
99	    public void setCity(String city) {
100	        this.city = city;
101	    }
102	
103	    public String getTelephone() {
104	        return this.telephone;
105	    }
106	
107	    public void setTelephone(String telephone) {
108	        this.telephone = telephone;
109	    }
110	
111	    /**
112	     * The stored E.164 {@link #telephone} formatted for humans as the country code, a single
113	     * space, then the national digits (the digits after the country code) grouped in threes from
114	     * the left, e.g. {@code "+61412345678"} becomes {@code "+61 412 345 678"}. The country code is
115	     * a single digit for the {@code +1} and {@code +7} zones and two digits otherwise.
116	     *
117	     * @return the human-formatted telephone, or the raw {@link #telephone} unchanged when it is
118	     *         {@code null} or not a {@code +} followed by digits
119	     */
120	    public String getTelephoneDisplay() {
121	        if (this.telephone == null || !this.telephone.matches("\\+[0-9]+")) {
122	            return this.telephone;
123	        }
124	        String digits = this.telephone.substring(1);
125	        int countryCodeLength = ONE_DIGIT_CALLING_CODES.contains(digits.substring(0, 1)) ? 1 : 2;
126	        if (digits.length() <= countryCodeLength) {
127	            return this.telephone;
128	        }
129	        String countryCode = digits.substring(0, countryCodeLength);
130	        String national = digits.substring(countryCodeLength);
131	        StringBuilder grouped = new StringBuilder();
132	        for (int i = 0; i < national.length(); i++) {
133	            if (i > 0 && i % 3 == 0) {
134	                grouped.append(' ');
135	            }
136	            grouped.append(national.charAt(i));
137	        }
138	        return "+" + countryCode + " " + grouped;
139	    }
140	
141	    /**
142	     * The E.164 calling codes that are a single digit ({@code +1} for the North American Numbering
143	     * Plan and {@code +7} for the Russia/Kazakhstan zone); every other calling code is two digits.
144	     */
145	    private static final Set<String> ONE_DIGIT_CALLING_CODES = Set.of("1", "7");
146	
147	    public String getEmail() {
148	        return this.email;
149	    }
150	
151	    public void setEmail(String email) {
152	        this.email = email;
153	    }
154	
155	    public String getPostcode() {
156	        return this.postcode;
157	    }
158	
159	    public void setPostcode(String postcode) {
160	        this.postcode = postcode;
161	    }
162	
163	    public LocalDate getRegistrationDate() {
164	        return this.registrationDate;
165	    }
166	
167	    public void setRegistrationDate(LocalDate registrationDate) {
168	        this.registrationDate = registrationDate;
169	    }
170	
171	    public LocalDate getBirthDate() {
172	        return this.birthDate;
173	    }
174	
175	    public void setBirthDate(LocalDate birthDate) {
176	        this.birthDate = birthDate;
177	    }
178	
179	    /**
180	     * The owner's age band, derived from the {@link #birthDate} measured in completed years
181	     * against the {@link #registrationDate}: {@code "MINOR"} when under 18, {@code "ADULT"}
182	     * from 18 to 64, and {@code "SENIOR"} at 65 and over.
183	     *
184	     * @return the age band, or {@code null} when either the birth date or the registration
185	     *         date has not been assigned
186	     */
187	    public String getAgeBand() {
188	        if (this.birthDate == null || this.registrationDate == null) {
189	            return null;
190	        }
191	        int age = java.time.Period.between(this.birthDate, this.registrationDate).getYears();
192	        if (age < 18) {
193	            return "MINOR";
194	        }
195	        if (age < 65) {
196	            return "ADULT";
197	        }
198	        return "SENIOR";
199	    }
200	
201	    public String getCustomerCode() {
202	        return this.customerCode;
203	    }
204	
205	    public void setCustomerCode(String customerCode) {
206	        this.customerCode = customerCode;
207	    }
208	
209	    public String getHouseholdId() {
210	        return this.householdId;
211	    }
212	
213	    public void setHouseholdId(String householdId) {
214	        this.householdId = householdId;
215	    }
216	
217	    public Integer getNamesakeCount() {
218	        return this.namesakeCount;
219	    }
220	
221	    public void setNamesakeCount(Integer namesakeCount) {
222	        this.namesakeCount = namesakeCount;
223	    }
224	
225	    /**
226	     * Whether more than 80 owners had already been created today at the time this owner
227	     * was created, indicating an unusually high signup volume.
228	     *
229	     * @return {@code true} when the bulk-signup threshold was exceeded, otherwise
230	     *         {@code false} (never {@code null})
231	     */
232	    public Boolean getBulkSignupWarning() {
233	        return this.bulkSignupWarning != null && this.bulkSignupWarning;
234	    }
235	
236	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
237	        this.bulkSignupWarning = bulkSignupWarning;
238	    }
239	
240	    /**
241	     * The number of owners in this owner's household (owners sharing the same
242	     * {@code householdId}) as of when this owner was created, used to derive the GOLD
243	     * membership tier.
244	     *
245	     * @return the household member count, or {@code null} if it has not been assigned
246	     */
247	    public Integer getHouseholdSize() {
248	        return this.householdSize;
249	    }
250	
251	    public void setHouseholdSize(Integer householdSize) {
252	        this.householdSize = householdSize;
253	    }
254	
255	    /**
256	     * Whether this owner, though not a hard duplicate, shares an existing owner's last name and
257	     * postcode while carrying a different telephone, flagging a likely duplicate registration.
258	     *
259	     * @return {@code true} when a soft-duplicate match was found on creation, otherwise
260	     *         {@code false} (never {@code null})
261	     */
262	    public Boolean getPossibleDuplicate() {
263	        return this.possibleDuplicate != null && this.possibleDuplicate;
264	    }
265	
266	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
267	        this.possibleDuplicate = possibleDuplicate;
268	    }
269	
270	    /**
271	     * The id of the existing owner this owner may duplicate (same last name and postcode,
272	     * different telephone), or {@code null} when this owner is not a possible duplicate.
273	     *
274	     * @return the matching owner id, or {@code null}
275	     */
276	    public Integer getPossibleDuplicateOf() {
277	        return this.possibleDuplicateOf;
278	    }
279	
280	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
281	        this.possibleDuplicateOf = possibleDuplicateOf;
282	    }
283	
284	    /**
285	     * The owner's name formatted as {@code "LastName, FirstName"} from the stored names.
286	     *
287	     * @return the formatted display name
288	     */
289	    public String getDisplayName() {
290	        return this.getLastName() + ", " + this.getFirstName();
291	    }
292	
293	    /**
294	     * The owner's initials: the upper-cased first letters of the first and last
295	     * names, dot-separated with a trailing dot (e.g. {@code "J.S."}).
296	     *
297	     * @return the formatted initials
298	     */
299	    public String getInitials() {
300	        return Character.toUpperCase(this.getFirstName().charAt(0)) + "."
301	            + Character.toUpperCase(this.getLastName().charAt(0)) + ".";
302	    }
303	
304	    /**
305	     * The owner's membership number formatted as {@code "<customerCode>-M<YY>"}, where
306	     * {@code YY} is the last two digits of the registration date's year (e.g.
307	     * {@code "NSW-1A2B3C4D-M26"}).
308	     *
309	     * @return the formatted membership number, or {@code null} if the customer code or
310	     *         registration date has not been assigned
311	     */
312	    public String getMembershipNumber() {
313	        if (this.customerCode == null || this.registrationDate == null) {
314	            return null;
315	        }
316	        return String.format("%s-M%02d", this.customerCode, this.registrationDate.getYear() % 100);
317	    }
318	
319	    /**
320	     * The owner's Luhn check digit: a single digit ({@code 0}-{@code 9}) computed with the
321	     * standard Luhn algorithm over the decimal digits contained in the {@code customerCode}
322	     * (non-digit characters are ignored).
323	     *
324	     * @return the Luhn check digit, or {@code null} if the customer code has not been assigned
325	     */
326	    public Integer getCheckDigit() {
327	        if (this.customerCode == null) {
328	            return null;
329	        }
330	        int sum = 0;
331	        boolean dbl = true;
332	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
333	            char c = this.customerCode.charAt(i);
334	            if (c < '0' || c > '9') {
335	                continue;
336	            }
337	            int d = c - '0';
338	            if (dbl) {
339	                d *= 2;
340	                if (d > 9) {
341	                    d -= 9;
342	                }
343	            }
344	            sum += d;
345	            dbl = !dbl;
346	        }
347	        return (10 - (sum % 10)) % 10;
348	    }
349	
350	    /**
351	     * The owner's numeric membership level, from {@code 1} to {@code 3}, computed on
352	     * creation. It starts at {@code 1}, gains {@code 1} when this owner carries an email
353	     * address, gains {@code 1} when this owner has no namesakes ({@code namesakeCount} is
354	     * {@code 0}), and is capped at {@code 3} (level {@code 4} is reserved for tenure).
355	     *
356	     * @return the membership level
357	     */
358	    public Integer getMembershipLevel() {
359	        int level = 1;
360	        boolean hasEmail = this.email != null && !this.email.isBlank();
361	        if (hasEmail) {
362	            level++;
363	        }
364	        boolean noNamesakes = this.namesakeCount != null && this.namesakeCount == 0;
365	        if (noNamesakes) {
366	            level++;
367	        }
368	        return Math.min(level, 3);
369	    }
370	
371	    /**
372	     * The owner's preferred contact channel: {@code "EMAIL"} when the owner carries an
373	     * email address, otherwise {@code "PHONE"}.
374	     *
375	     * @return {@code "EMAIL"} when an email is present, otherwise {@code "PHONE"}
376	     */
377	    public String getContactPreference() {
378	        boolean hasEmail = this.email != null && !this.email.isBlank();
379	        return hasEmail ? "EMAIL" : "PHONE";
380	    }
381	
382	    /**
383	     * The owner's identity key: the single derived value used for duplicate detection, formed as
384	     * {@code normalizedTelephone + "|" + (email or empty) + "|" + householdId}. The telephone and
385	     * email are the already-normalized stored values and a {@code null} email or household id is
386	     * rendered as the empty string. Two owners are duplicates only when their whole identity keys
387	     * are equal; because the telephone is part of the key, household members with different
388	     * telephones have different identity keys.
389	     *
390	     * @return the derived identity key
391	     */
392	    public String getIdentityKey() {
393	        String telephonePart = this.telephone == null ? "" : this.telephone;
394	        String emailPart = this.email == null ? "" : this.email;
395	        String householdPart = this.householdId == null ? "" : this.householdId;
396	        return telephonePart + "|" + emailPart + "|" + householdPart;
397	    }
398	
399	    /**
400	     * City -> canonical region, the fixed ground truth for deriving locality.
401	     */
402	    private static final Map<String, String> CITY_REGION = Map.of(
403	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
404	
405	    /**
406	     * Region -> inclusive 4-digit postcode range {@code {low, high}}, the fixed ground truth for
407	     * deriving locality from the postcode ahead of the city.
408	     */
409	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
410	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
411	
412	    /**
413	     * The owner's locality: the canonical region resolved by the postcode range first
414	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}), falling back to the
415	     * fixed city-to-region table ({@code Sydney->NSW}, {@code Melbourne->VIC},
416	     * {@code Brisbane->QLD}) when the postcode is absent or in no known range, or {@code "UNKNOWN"}
417	     * when the city is not in the table either. The postcode takes precedence so cities that share a
418	     * name are disambiguated by their postcode's region.
419	     *
420	     * @return the canonical region string, or {@code "UNKNOWN"}
421	     */
422	    public String getLocality() {
423	        String byPostcode = regionForPostcode(this.postcode);
424	        if (byPostcode != null) {
425	            return byPostcode;
426	        }
427	        return CITY_REGION.getOrDefault(this.city, "UNKNOWN");
428	    }
429	
430	    /**
431	     * Region whose postcode range contains the given postcode, or {@code null} when the postcode is
432	     * absent, not a 4-digit number, or in no known range.
433	     *
434	     * @param postcode the owner's postcode (may be {@code null})
435	     * @return the matching region, or {@code null}
436	     */
437	    private static String regionForPostcode(String postcode) {
438	        if (postcode == null || !postcode.matches("\\d{4}")) {
439	            return null;
440	        }
441	        int value = Integer.parseInt(postcode);
442	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
443	            int[] range = entry.getValue();
444	            if (value >= range[0] && value <= range[1]) {
445	                return entry.getKey();
446	            }
447	        }
448	        return null;
449	    }
450	
451	    protected Set<Pet> getPetsInternal() {
452	        if (this.pets == null) {
453	            this.pets = new HashSet<>();
454	        }
455	        return this.pets;
456	    }
457	
458	    protected void setPetsInternal(Set<Pet> pets) {
459	        this.pets = pets;
460	    }
461	
462	    public List<Pet> getPets() {
463	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
464	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
465	        return Collections.unmodifiableList(sortedPets);
466	    }
467	
468	    public void setPets(List<Pet> pets) {
469	        this.pets = new HashSet<>(pets);
470	    }
471	
472	    public void addPet(Pet pet) {
473	        getPetsInternal().add(pet);
474	        pet.setOwner(this);
475	    }
476	
477	    /**
478	     * Return the Pet with the given name, or null if none found for this Owner.
479	     *
480	     * @param name to test
481	     * @return true if pet name is already in use
482	     */
483	    public Pet getPet(String name) {
484	        return getPet(name, false);
485	    }
486	
487	    /**
488	     * Return the Pet with the given name, or null if none found for this Owner.
489	     *
490	     * @param name to test
491	     * @return true if pet name is already in use
492	     */
493	    public Pet getPet(String name, boolean ignoreNew) {
494	        name = name.toLowerCase();
495	        for (Pet pet : getPetsInternal()) {
496	            if (!ignoreNew || !pet.isNew()) {
497	                String compName = pet.getName();
498	                compName = compName.toLowerCase();
499	                if (compName.equals(name)) {
500	                    return pet;
501	                }
502	            }
503	        }
504	        return null;
505	    }
506	
507	    public Pet getPet(Integer petId) {
508	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
509	    }
510	
511	    @Override
512	    public String toString() {
513	        return new ToStringCreator(this)
514	
515	            .append("id", this.getId())
516	            .append("new", this.isNew())
517	            .append("lastName", this.getLastName())
518	            .append("firstName", this.getFirstName())
519	            .append("address", this.address)
520	            .append("city", this.city)
521	            .append("telephone", this.telephone)
522	            .append("email", this.email)
523	            .toString();
524	    }
525	}
