66	    /**
67	     * Pattern for a syntactically valid email address: a non-empty local part, an '@', and a
68	     * dotted domain ending in a letters-only label. Applied to the trimmed, lower-cased value.
69	     */
70	    /**
71	     * Dedicated audit logger. Successful side-effects (e.g. owner creation) are recorded here so
72	     * they can be routed and asserted independently of the application's diagnostic logging.
73	     */
74	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
75	
76	    private static final Pattern EMAIL_PATTERN =
77	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$");
78	
79	    /**
80	     * Common address abbreviations expanded to their full form during address normalization.
81	     * Matching is performed per whitespace-separated token on the upper-cased value.
82	     */
83	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
84	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
85	
86	    /**
87	     * Required national-number length (the digits after the country code) per E.164 country code.
88	     * A number whose country code appears here must carry exactly the mapped number of national
89	     * digits; country codes not listed fall back to the generic 8-to-15 total-digit rule.
90	     */
91	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS =
92	        Map.of("61", 9, "1", 10);
93	
94	    /**
95	     * Inclusive 4-digit postcode range {@code {low, high}} per region, the fixed ground truth for
96	     * validating an owner's postcode against the region derived from its city. A region not listed
97	     * here (e.g. the {@code "UNKNOWN"} locality of an unmapped city) imposes no range constraint, so
98	     * any 4-digit postcode is accepted.
99	     */
100	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
101	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
102	
103	    private final ClinicService clinicService;
104	
105	    private final OwnerMapper ownerMapper;
106	
