146	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
147	    @Override
148	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
149	        HttpHeaders headers = new HttpHeaders();
150	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
151	        LocalDate suppliedDate = owner.getRegistrationDate();
152	        if (suppliedDate != null && suppliedDate.isAfter(LocalDate.now())) {
153	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
154	        }
155	        LocalDate effectiveDate = suppliedDate != null ? suppliedDate : LocalDate.now();
156	        LocalDate registrationDate = toBusinessDay(effectiveDate);
157	        owner.setRegistrationDate(registrationDate);
158	        long createdToday = this.clinicService.findAllOwners().stream()
159	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
160	            .count();
161	        if (createdToday >= 100) {
162	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
163	        }
164	        owner.setBulkSignupWarning(createdToday > 80);
165	        String address = normalizeAddress(owner.getAddress());
166	        if (address == null || address.isEmpty()) {
167	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
168	        }
169	        owner.setAddress(address);
170	        String telephone = toE164(owner.getTelephone());
171	        if (telephone == null) {
172	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
173	        }
174	        owner.setTelephone(telephone);
175	        if (owner.getEmail() != null) {
176	            String email = normalizeEmail(owner.getEmail());
177	            if (!EMAIL_PATTERN.matcher(email).matches()) {
178	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
179	            }
180	            owner.setEmail(email);
181	        }
182	        if (!isPostcodeValidForCity(owner.getPostcode(), owner.getLocality())) {
183	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
184	        }
185	        String cityKey = householdKey(owner.getCity());
186	        long cityCount = this.clinicService.findAllOwners().stream()
187	            .filter(existing -> existing.getCity() != null
188	                && cityKey.equals(householdKey(existing.getCity())))
189	            .count();
190	        if (cityCount >= 50) {
191	            return new ResponseEntity<>(HttpStatus.CONFLICT);
192	        }
193	        // The household is keyed on (normalized last name, postcode): every owner derives the same
194	        // deterministic householdId from those two fields, so owners sharing them are the same
195	        // household. This computed id is what duplicate detection and the household size below key off.
196	        String householdId = householdId(owner);
197	        owner.setHouseholdId(householdId);
198	        List<Owner> householdMembers = this.clinicService.findAllOwners().stream()
199	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
200	            .toList();
201	        owner.setHouseholdSize(householdMembers.size() + 1);
202	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
203	        // Household-duplicate block: a second owner in an existing household (same computed
204	        // householdId) is rejected as a duplicate. 'sharesHousehold' now only BYPASSES this block —
205	        // declaring the new owner a member — rather than creating the household link itself.
206	        if (!householdMembers.isEmpty() && !sharesHousehold) {
207	            return new ResponseEntity<>(HttpStatus.CONFLICT);
208	        }
209	        // Single consolidated duplicate check: the telephone, email and household duplicate rules are
210	        // all expressed through the one derived identityKey (telephone|email|householdId). A create is
211	        // rejected only when a new owner's WHOLE identityKey equals an existing owner's; because the
212	        // telephone is part of the key, two household members with different telephones are allowed.
213	        // This still catches a full identity repeat even when it declares sharesHousehold.
214	        String identityKey = owner.getIdentityKey();
215	        boolean identityInUse = this.clinicService.findAllOwners().stream()
216	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
217	        if (identityInUse) {
218	            return new ResponseEntity<>(HttpStatus.CONFLICT);
219	        }
220	        // Soft-duplicate detection. A declared household member (sharesHousehold) is never a suspected
221	        // duplicate. Any other owner sharing an existing owner's last name and postcode with a
222	        // different telephone is now, by definition, a household duplicate already rejected above, so
223	        // it never reaches this point; the check is retained for owners that are not household matches.
224	        if (sharesHousehold) {
225	            owner.setPossibleDuplicate(false);
226	        } else {
227	            String softDuplicateLastNameKey = householdKey(owner.getLastName());
228	            String softDuplicatePostcode = owner.getPostcode();
229	            String softDuplicateTelephone = owner.getTelephone();
230	            Owner possibleDuplicate = softDuplicatePostcode == null ? null
231	                : this.clinicService.findAllOwners().stream()
232	                    .filter(existing -> softDuplicateLastNameKey.equals(householdKey(existing.getLastName())))
233	                    .filter(existing -> softDuplicatePostcode.equals(existing.getPostcode()))
234	                    .filter(existing -> !softDuplicateTelephone.equals(existing.getTelephone()))
235	                    .min(Comparator.comparing(Owner::getId))
236	                    .orElse(null);
237	            if (possibleDuplicate != null) {
238	                owner.setPossibleDuplicate(true);
239	                owner.setPossibleDuplicateOf(possibleDuplicate.getId());
240	            } else {
241	                owner.setPossibleDuplicate(false);
242	            }
243	        }
244	        owner.setCustomerCode(customerCode(owner));
245	        String firstNameKey = householdKey(owner.getFirstName());
246	        String namesakeLastNameKey = householdKey(owner.getLastName());
247	        long namesakeCount = this.clinicService.findAllOwners().stream()
248	            .filter(existing -> firstNameKey.equals(householdKey(existing.getFirstName()))
249	                && namesakeLastNameKey.equals(householdKey(existing.getLastName())))
250	            .count();
251	        owner.setNamesakeCount((int) namesakeCount);
252	        this.clinicService.saveOwner(owner);
253	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
254	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
255	            owner.getMembershipLevel());
256	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
257	        headers.setLocation(UriComponentsBuilder.newInstance()
258	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
259	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
260	    }
261	
262	    /**
263	     * Validates an owner's postcode against the region derived from its city. The postcode is
264	     * optional: a {@code null} value is always accepted. When present it must fall within the
265	     * inclusive range mapped to the region by {@link #REGION_POSTCODES}; a region with no known
266	     * range (e.g. the {@code "UNKNOWN"} locality of an unmapped city) accepts any 4-digit postcode.
267	     * The 4-digit syntax itself is enforced upstream by bean validation.
268	     *
269	     * @param postcode the owner's postcode (may be {@code null})
270	     * @param locality the region derived from the owner's city
271	     * @return {@code true} when the postcode is absent, the region has no range, or the postcode is
272	     *         within the region's range; {@code false} when it is out of range
273	     */
274	    private boolean isPostcodeValidForCity(String postcode, String locality) {
275	        if (postcode == null) {
276	            return true;
277	        }
278	        int[] range = REGION_POSTCODES.get(locality);
279	        if (range == null) {
280	            return true;
281	        }
282	        int value = Integer.parseInt(postcode);
283	        return value >= range[0] && value <= range[1];
284	    }
285	
286	    /**
287	     * Normalizes a telephone number into E.164 form. Spaces, dashes and brackets are stripped.
288	     * When the value carries a leading {@code '+'} its country code is kept as given; otherwise the
289	     * Australian country code {@code '+61'} is assumed and a single leading {@code '0'} is dropped
290	     * from the national digits. The result must carry 8 to 15 digits after the {@code '+'}. For
291	     * recognised country codes the national number (the digits after the country code) must also be
292	     * exactly the length that country requires ({@code '+61'} needs 9 national digits, {@code '+1'}
293	     * needs 10); a wrong national-number length yields {@code null}.
294	     *
295	     * @param telephone the raw telephone value (may be {@code null})
296	     * @return the E.164 telephone (e.g. {@code "+61412345678"}), or {@code null} if it cannot form
297	     *         a valid E.164 number
298	     */
299	    private String toE164(String telephone) {
300	        if (telephone == null) {
301	            return null;
302	        }
303	        String trimmed = telephone.trim();
304	        boolean hasCountryCode = trimmed.startsWith("+");
305	        String cleaned = trimmed.replaceAll("[\\s()\\[\\]-]", "");
306	        if (hasCountryCode) {
307	            cleaned = cleaned.substring(1);
308	        }
309	        if (!cleaned.matches("[0-9]+")) {
310	            return null;
311	        }
312	        String digits;
313	        if (hasCountryCode) {
314	            digits = cleaned;
315	        } else {
316	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
317	            digits = "61" + national;
318	        }
319	        if (digits.length() < 8 || digits.length() > 15) {
320	            return null;
321	        }
322	        if (!hasValidNationalNumberLength(digits)) {
323	            return null;
324	        }
325	        return "+" + digits;
326	    }
327	
328	    /**
329	     * Checks the national-number length of an E.164 digit string (country code plus national
330	     * number, without the leading {@code '+'}) against its country code. When the number's country
331	     * code is one of the {@link #NATIONAL_NUMBER_LENGTHS recognised codes}, the digits after the
332	     * country code must number exactly what that country requires; the longest matching country
333	     * code wins. Numbers whose country code is not recognised are accepted here (they are governed
334	     * only by the generic total-length rule).
335	     *
336	     * @param digits the E.164 digits without the leading {@code '+'} (e.g. {@code "61412345678"})
337	     * @return {@code true} if the national-number length is acceptable for the country code
338	     */
339	    private boolean hasValidNationalNumberLength(String digits) {
340	        return NATIONAL_NUMBER_LENGTHS.entrySet().stream()
341	            .filter(entry -> digits.startsWith(entry.getKey()))
342	            .max(Comparator.comparingInt(entry -> entry.getKey().length()))
343	            .map(entry -> digits.length() - entry.getKey().length() == entry.getValue())
344	            .orElse(true);
345	    }
346	
347	    /**
348	     * Normalizes an email address for storage by trimming surrounding whitespace and lower-casing
349	     * it. The result is validated by the caller against {@link #EMAIL_PATTERN}.
350	     *
351	     * @param email the raw email value (must not be {@code null})
352	     * @return the trimmed, lower-cased email
353	     */
354	    private String normalizeEmail(String email) {
355	        return email.trim().toLowerCase(Locale.ROOT);
356	    }
357	
358	    /**
359	     * Normalizes a postal address for storage and comparison: surrounding whitespace is trimmed,
360	     * internal runs of whitespace are collapsed to a single space, the value is upper-cased and
361	     * common street-type abbreviations are expanded per token ({@code ST -> STREET},
362	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}). The stored and returned address is this
363	     * normalized form, and every household comparison uses it.
364	     *
365	     * @param address the raw address value (may be {@code null})
366	     * @return the normalized address, or {@code null} if the input was {@code null}
367	     */
368	    private String normalizeAddress(String address) {
369	        if (address == null) {
370	            return null;
371	        }
372	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
373	        if (collapsed.isEmpty()) {
374	            return collapsed;
375	        }
376	        String[] tokens = collapsed.split(" ");
377	        StringBuilder sb = new StringBuilder(collapsed.length());
378	        for (int i = 0; i < tokens.length; i++) {
379	            if (i > 0) {
380	                sb.append(' ');
381	            }
382	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
383	        }
384	        return sb.toString();
385	    }
386	
387	    /**
388	     * Normalizes a value for household-duplicate comparison: surrounding whitespace is trimmed,
389	     * internal runs of whitespace are collapsed to a single space and the result is lower-cased,
390	     * so that owners are compared case-insensitively with collapsed whitespace.
391	     *
392	     * @param value the raw value (must not be {@code null})
393	     * @return the normalized comparison key
394	     */
395	    private String householdKey(String value) {
396	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
397	    }
398	
399	    /**
400	     * Derives a stable, shared household identifier for the owner's household: the first 12 hex
401	     * characters of the SHA-256 digest of {@code normalizedLastName + '|' + postcode}, where the
402	     * last name is normalized with {@link #householdKey} and an absent postcode is rendered as the
403	     * empty string. Because it is a pure function of the last name and postcode, every owner sharing
404	     * those two fields derives the identical identifier and therefore belongs to the same household.
405	     *
406	     * @param owner the owner whose household identifier is derived
407	     * @return the stable household identifier
408	     */
409	    private String householdId(Owner owner) {
410	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
411	        String key = householdKey(owner.getLastName()) + "|" + postcode;
412	        try {
413	            byte[] digest = MessageDigest.getInstance("SHA-256")
414	                .digest(key.getBytes(StandardCharsets.UTF_8));
415	            StringBuilder sb = new StringBuilder(digest.length * 2);
416	            for (byte b : digest) {
417	                sb.append(String.format("%02x", b));
418	            }
419	            return sb.substring(0, 12);
420	        }
421	        catch (java.security.NoSuchAlgorithmException e) {
422	            throw new IllegalStateException("SHA-256 not available", e);
423	        }
424	    }
425	
426	    /**
427	     * Builds the customer code for a newly registered owner in the form
428	     * {@code '<REGION>-<HASH8>'}, where {@code REGION} is the region code derived from the owner's
429	     * postcode (the same region derivation shared with {@link Owner#getLocality() locality}:
430	     * postcode range first, falling back to the city, or {@code 'UNKNOWN'}) and {@code HASH8} is the
431	     * first 8 upper-case hex characters of the SHA-256 digest of the normalized telephone
432	     * concatenated with the last name (e.g. {@code 'NSW-1A2B3C4D'}). Sequence numbers are not used,
433	     * so the code is a pure function of the owner's region and identity.
434	     *
435	     * @param owner the owner whose customer code is derived (with normalized telephone already set)
436	     * @return the assigned customer code
437	     */
438	    private String customerCode(Owner owner) {
439	        String region = owner.getLocality();
440	        String hash8 = sha256UpperHex(owner.getTelephone() + owner.getLastName(), 8);
441	        return region + "-" + hash8;
442	    }
443	
444	    /**
445	     * Returns the first {@code length} upper-case hex characters of the SHA-256 digest of the
446	     * UTF-8 bytes of {@code input}.
447	     *
448	     * @param input  the value to hash
449	     * @param length the number of leading hex characters to keep
450	     * @return the truncated, upper-cased hex digest
451	     */
452	    private String sha256UpperHex(String input, int length) {
453	        try {
454	            byte[] digest = MessageDigest.getInstance("SHA-256")
455	                .digest(input.getBytes(StandardCharsets.UTF_8));
456	            StringBuilder sb = new StringBuilder(digest.length * 2);
457	            for (byte b : digest) {
458	                sb.append(String.format("%02x", b));
459	            }
460	            return sb.substring(0, length).toUpperCase(Locale.ROOT);
461	        }
462	        catch (java.security.NoSuchAlgorithmException e) {
463	            throw new IllegalStateException("SHA-256 not available", e);
464	        }
465	    }
466	
467	    /**
468	     * Rolls a registration date forward onto a business day. When the given date falls on a
469	     * Saturday or Sunday it is advanced to the following Monday; a weekday is returned unchanged.
470	     *
471	     * @param date the effective registration date (must not be {@code null})
472	     * @return the same date if it is a weekday, otherwise the next Monday
473	     */
474	    private LocalDate toBusinessDay(LocalDate date) {
475	        DayOfWeek dayOfWeek = date.getDayOfWeek();
476	        if (dayOfWeek == DayOfWeek.SATURDAY) {
477	            return date.plusDays(2);
478	        }
479	        if (dayOfWeek == DayOfWeek.SUNDAY) {
480	            return date.plusDays(1);
481	        }
482	        return date;
483	    }
484	
485	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
486	    @Override
487	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
488	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
489	        if (currentOwner == null) {
490	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
491	        }
492	        String email = ownerFieldsDto.getEmail();
493	        if (email != null) {
494	            email = normalizeEmail(email);
495	            if (!EMAIL_PATTERN.matcher(email).matches()) {
496	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
497	            }
498	        }
499	        String telephone = toE164(ownerFieldsDto.getTelephone());
500	        if (telephone == null) {
501	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
502	        }
503	        currentOwner.setAddress(ownerFieldsDto.getAddress());
504	        currentOwner.setCity(ownerFieldsDto.getCity());
505	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
506	        currentOwner.setLastName(ownerFieldsDto.getLastName());
507	        currentOwner.setTelephone(telephone);
508	        currentOwner.setEmail(email);
509	        this.clinicService.saveOwner(currentOwner);
510	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
511	    }
512	
513	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
514	    @Transactional
515	    @Override
516	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
517	        Owner owner = this.clinicService.findOwnerById(ownerId);
518	        if (owner == null) {
519	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
520	        }
521	        this.clinicService.deleteOwner(owner);
522	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
523	    }
524	
525	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
526	    @Override
527	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
528	        Owner owner = this.clinicService.findOwnerById(ownerId);
529	        if (owner == null) {
530	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
531	        }
532	        HttpHeaders headers = new HttpHeaders();
533	        Pet pet = petMapper.toPet(petFieldsDto);
534	        owner.setId(ownerId);
535	        pet.setOwner(owner);
536	        pet.getType().setName(null);
537	        this.clinicService.savePet(pet);
538	        PetDto petDto = petMapper.toPetDto(pet);
539	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
540	            .buildAndExpand(pet.getId()).toUri());
541	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
542	    }
543	
544	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
545	    @Override
546	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
547	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
548	        if (currentOwner != null) {
549	            Pet currentPet = this.clinicService.findPetById(petId);
550	            if (currentPet != null) {
551	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
552	                currentPet.setName(petFieldsDto.getName());
553	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
554	                this.clinicService.savePet(currentPet);
555	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
556	            }
557	        }
558	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
559	    }
560	
561	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
562	    @Override
563	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
564	        HttpHeaders headers = new HttpHeaders();
565	        Visit visit = visitMapper.toVisit(visitFieldsDto);
566	        Pet pet = new Pet();
567	        pet.setId(petId);
568	        visit.setPet(pet);
569	        this.clinicService.saveVisit(visit);
570	        VisitDto visitDto = visitMapper.toVisitDto(visit);
571	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
572	            .buildAndExpand(visit.getId()).toUri());
573	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
574	    }
575	
576	
577	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
578	    @Override
579	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
580	        Owner owner = this.clinicService.findOwnerById(ownerId);
581	        if (owner != null) {
582	            Pet pet = owner.getPet(petId);
583	            if (pet != null) {
584	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
585	            }
586	        }
587	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
588	    }
589	}
